using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;

namespace ContosoUniversity.Tests;

public static class TestHelpers
{
    public static SchoolContext CreateInMemoryContext(string? dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        return new SchoolContext(options);
    }

    public static void SeedStudents(SchoolContext context)
    {
        context.Students.AddRange(
            new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01") },
            new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01") },
            new Student { FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01") }
        );
        context.SaveChanges();
    }

    public static void SeedDepartmentsAndCourses(SchoolContext context)
    {
        var instructor = new Instructor { FirstMidName = "Kim", LastName = "Abercrombie", HireDate = DateTime.Parse("1995-03-11") };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var dept = new Department { Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructor.ID };
        context.Departments.Add(dept);
        context.SaveChanges();

        context.Courses.AddRange(
            new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = dept.DepartmentID },
            new Course { CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = dept.DepartmentID }
        );
        context.SaveChanges();
    }

    public static void SeedFullDatabase(SchoolContext context)
    {
        SeedStudents(context);
        SeedDepartmentsAndCourses(context);

        var students = context.Students.ToList();
        var courses = context.Courses.ToList();

        context.Enrollments.Add(new Enrollment
        {
            StudentID = students[0].ID,
            CourseID = courses[0].CourseID,
            Grade = Grade.A
        });
        context.SaveChanges();
    }
}

using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_WithItems_SetsPageIndexAndTotalPages()
    {
        // Arrange
        var items = new List<string> { "a", "b", "c" };

        // Act
        var list = new PaginatedList<string>(items, 10, 2, 3);

        // Assert
        Assert.Equal(2, list.PageIndex);
        Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        Assert.Equal(3, list.Count);
        Assert.Equal("a", list[0]);
        Assert.Equal("b", list[1]);
        Assert.Equal("c", list[2]);
    }

    [Theory]
    [InlineData(10, 1, 5, 2)]  // 10 items, page 1, 5 per page => 2 pages
    [InlineData(10, 2, 5, 2)]
    [InlineData(11, 1, 5, 3)]  // ceil(11/5) = 3
    [InlineData(1, 1, 10, 1)]
    [InlineData(0, 1, 10, 0)]  // 0 items => 0 total pages
    public void Constructor_VariousCounts_CalculatesTotalPagesCorrectly(int count, int pageIndex, int pageSize, int expectedTotalPages)
    {
        // Act
        var list = new PaginatedList<int>(new List<int>(), count, pageIndex, pageSize);

        // Assert
        Assert.Equal(expectedTotalPages, list.TotalPages);
        Assert.Equal(pageIndex, list.PageIndex);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);
        Assert.False(list.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        var list = new PaginatedList<int>(new List<int>(), 10, 2, 5);
        Assert.True(list.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int>(), 10, 2, 5);
        Assert.False(list.HasNextPage);
    }

    [Fact]
    public void HasNextPage_FirstPageOfMultiple_ReturnsTrue()
    {
        var list = new PaginatedList<int>(new List<int>(), 10, 1, 5);
        Assert.True(list.HasNextPage);
    }

    [Fact]
    public void HasNextPage_SinglePage_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int>(), 3, 1, 5);
        Assert.False(list.HasNextPage);
    }

    [Fact]
    public void Create_ReturnsCorrectPageOfItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 20).AsQueryable();

        // Act
        var page1 = PaginatedList<int>.Create(source, 1, 5);
        var page2 = PaginatedList<int>.Create(source, 2, 5);
        var page4 = PaginatedList<int>.Create(source, 4, 5);

        // Assert
        Assert.Equal(5, page1.Count);
        Assert.Equal(1, page1[0]);
        Assert.Equal(5, page1[4]);
        Assert.Equal(4, page1.TotalPages);

        Assert.Equal(5, page2.Count);
        Assert.Equal(6, page2[0]);
        Assert.Equal(10, page2[4]);

        Assert.Equal(5, page4.Count);
        Assert.Equal(16, page4[0]);
        Assert.Equal(20, page4[4]);
    }

    [Fact]
    public void Create_LastPagePartial_ReturnsRemainingItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 7).AsQueryable();

        // Act
        var page2 = PaginatedList<int>.Create(source, 2, 5);

        // Assert
        Assert.Equal(2, page2.Count);
        Assert.Equal(6, page2[0]);
        Assert.Equal(7, page2[1]);
        Assert.Equal(2, page2.TotalPages);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }
}

using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain the static queue to isolate tests
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain after test
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_EnqueuesNotificationWithCorrectMessage()
    {
        // Act
        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("Student 'John Doe'", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        // Act
        _sut.SendNotification("Course", "101", null, EntityOperation.UPDATE, "teacher");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Course (ID: 101)", notification.Message);
        Assert.Contains("updated", notification.Message);
        Assert.Equal("teacher", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
    {
        // Act
        _sut.SendNotification("Department", "5", "Math", EntityOperation.DELETE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("deleted", notification.Message);
        Assert.Equal("DELETE", notification.Operation);
    }

    [Fact]
    public void SendNotification_WithoutUserName_DefaultsToSystem()
    {
        // Act
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_TwoArgOverload_EnqueuesCorrectly()
    {
        // Act
        _sut.SendNotification("Instructor", "7", EntityOperation.UPDATE, "user1");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor", notification.EntityType);
        Assert.Equal("7", notification.EntityId);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_MultipleMessages_ReturnsFIFOOrder()
    {
        // Arrange
        _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);
        _sut.SendNotification("C", "3", "Third", EntityOperation.DELETE);

        // Act & Assert
        var first = _sut.ReceiveNotification();
        Assert.Equal("A", first!.EntityType);

        var second = _sut.ReceiveNotification();
        Assert.Equal("B", second!.EntityType);

        var third = _sut.ReceiveNotification();
        Assert.Equal("C", third!.EntityType);

        Assert.Null(_sut.ReceiveNotification());
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToNow()
    {
        var before = DateTime.Now.AddSeconds(-1);

        _sut.SendNotification("X", "1", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.True(notification.CreatedAt >= before);
        Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation
        var ex = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(ex);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var ex = Record.Exception(() => service.Dispose());
        Assert.Null(ex);
    }
}

