    [Fact]
    public void Context_CourseAssignment_CompositeKey()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Today };
        context.Instructors.Add(instructor);
