+
+namespace ContosoUniversity.Tests;
+
+public class DbInitializerTests
+{
+    [Fact]
+    public void Initialize_EmptyDatabase_SeedsStudents()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        Assert.Equal(8, context.Students.Count());
+    }
+
+    [Fact]
+    public void Initialize_EmptyDatabase_SeedsInstructors()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        Assert.Equal(5, context.Instructors.Count());
+    }
+
+    [Fact]
+    public void Initialize_EmptyDatabase_SeedsDepartments()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        Assert.Equal(4, context.Departments.Count());
+        Assert.Contains(context.Departments, d => d.Name == "English");
+        Assert.Contains(context.Departments, d => d.Name == "Mathematics");
+        Assert.Contains(context.Departments, d => d.Name == "Engineering");
+        Assert.Contains(context.Departments, d => d.Name == "Economics");
+    }
+
+    [Fact]
+    public void Initialize_EmptyDatabase_SeedsCourses()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        Assert.Equal(7, context.Courses.Count());
+        Assert.Contains(context.Courses, c => c.Title == "Chemistry");
+        Assert.Contains(context.Courses, c => c.Title == "Calculus");
+    }
+
+    [Fact]
+    public void Initialize_EmptyDatabase_SeedsEnrollments()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        Assert.Equal(11, context.Enrollments.Count());
+    }
+
+    [Fact]
+    public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        Assert.Equal(3, context.OfficeAssignments.Count());
+    }
+
+    [Fact]
+    public void Initialize_EmptyDatabase_SeedsCourseAssignments()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        Assert.Equal(8, context.CourseAssignments.Count());
+    }
+
+    [Fact]
+    public void Initialize_AlreadySeeded_DoesNotDuplicate()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        // Seed twice
+        DbInitializer.Initialize(context);
+        DbInitializer.Initialize(context);
+
+        // Should still have the same number
+        Assert.Equal(8, context.Students.Count());
+        Assert.Equal(5, context.Instructors.Count());
+    }
+
+    [Fact]
+    public void Initialize_StudentData_HasCorrectProperties()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        var carson = context.Students.First(s => s.LastName == "Alexander");
+        Assert.Equal("Carson", carson.FirstMidName);
+        Assert.Equal(DateTime.Parse("2010-09-01"), carson.EnrollmentDate);
+    }
+
+    [Fact]
+    public void Initialize_Enrollments_NoDuplicates()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        // All enrollments should be unique by (StudentID, CourseID)
+        var groups = context.Enrollments
+            .GroupBy(e => new { e.StudentID, e.CourseID })
+            .ToList();
+
+        Assert.All(groups, g => Assert.Single(g));
+    }
+
+    [Fact]
+    public void Initialize_Departments_HaveAdministrators()
+    {
+        using var context = TestHelpers.CreateInMemoryContext();
+
+        DbInitializer.Initialize(context);
+
+        var departments = context.Departments.ToList();
+        Assert.All(departments, d => Assert.NotNull(d.InstructorID));
+    }
+}
